{"content":"/* ============================================================
   STYLE.CSS — Persona 5-Style Portfolio
   Single source of truth for all visual styles.
   ============================================================ */

/* ------------------------------------------------------------
   1. DESIGN TOKENS — P5 Palette & Global Custom Properties
   ------------------------------------------------------------ */
:root {
  /* P5 Palette */
  --color-red:   #E61C1C;
  --color-black: #0D0D0D;
  --color-white: #FFFFFF;
  --color-gold:  #F0C040;

  /* Derived surface colours */
  --color-surface-dark:  #141414;
  --color-surface-light: #F5F5F5;
  --color-text-on-dark:  var(--color-white);
  --color-text-on-light: var(--color-black);

  /* Typography */
  --font-heading: 'Oswald', 'Anton', sans-serif;
  --font-body:    system-ui, -apple-system, 'Segoe UI', sans-serif;

  /* Spacing scale (rem-based) */
  --space-xs:  0.5rem;   /*  8px */
  --space-sm:  1rem;     /* 16px */
  --space-md:  2rem;     /* 32px */
  --space-lg:  4rem;     /* 64px */
  --space-xl:  8rem;     /* 128px */

  /* Animation timing */
  --duration-fast:   200ms;
  --duration-enter:  800ms;
  --duration-hero:   1500ms;
  --ease-out:        cubic-bezier(0.22, 1, 0.36, 1);

  /* Z-index layers */
  --z-nav: 100;
}

/* ------------------------------------------------------------
   2. CSS RESET & BASE
   ------------------------------------------------------------ */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 100%; /* 16px base */
}

body {
  font-family: var(--font-body);
  background-color: var(--color-black);
  color: var(--color-white);
  line-height: 1.6;
  overflow-x: hidden;
}

img,
svg {
  display: block;
  max-width: 100%;
  height: auto; /* prevent aspect-ratio distortion */
}

a {
  color: inherit;
  text-decoration: none;
}

ul {
  list-style: none;
}

button {
  font: inherit;
  cursor: pointer;
  background: none;
  border: none;
}

/* ------------------------------------------------------------
   3. SECTIONS — common layout defaults
   ------------------------------------------------------------ */
main {
  display: block;
  width: 100%;
}

.section {
  position: relative;
  overflow: hidden;
  padding: var(--space-xl) var(--space-md);
}

/* ------------------------------------------------------------
   4. TYPOGRAPHY — headings & section heading accent
   ------------------------------------------------------------ */
h1, h2, h3 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.1;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.section__heading {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 700;
