  animation: heroReveal 1200ms var(--ease-out) both;
  animation-delay: var(--delay, 0ms);
}

/* Hero reveal keyframes */
@keyframes heroReveal {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

