.nav__link::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--color-red);
  transition: width var(--duration-fast) var(--ease-out);
}

.nav__link:hover::after,
.nav__link--active::after {
  width: 100%;
}

.nav__link--active {
  color: var(--color-red);
}

.nav__link:focus-visible {
  outline: 2px solid var(--color-red);
  outline-offset: 4px;
}

